from rest_framework import serializers, viewsets, permissions
from .models import CustomerSubscription, StoredPaymentMethod

class CustomerSubscriptionSerializer(serializers.HyperlinkedModelSerializer):
    payment_method = serializers.HyperlinkedRelatedField(
        view_name='paymentmethod-detail',
        queryset=StoredPaymentMethod.objects.none()
    )

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        request = self.context.get('request')
        if request and hasattr(request, 'user'):
            self.fields['payment_method'].queryset = StoredPaymentMethod.objects.filter(owner=request.user)

    class Meta:
        model = CustomerSubscription
        fields = ('url', 'id', 'plan_name', 'billing_interval', 'payment_method')

class CustomerSubscriptionViewSet(viewsets.ModelViewSet):
    serializer_class = CustomerSubscriptionSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return CustomerSubscription.objects.filter(customer=self.request.user)
